import {brandKey,brandDirectory} from './brand-core.mjs';
import {TYPE_ORDER,BANDS,freshState,filterCatalog,catalogNavigation,parseSearch,money,comparable,isListed} from './catalog-core.mjs';
import {normalizePreferences,PERSONAL_TYPES,withinBudget,upgradeReason,personalMatch,suggestions} from './personal-core.mjs';
import {shopIcon} from './shop-icons.mjs';
const {items:catalogItems,meta}=window.CATALOG;
const brandPicks=window.BRAND_PICKS?.picks||[];
let selectedBrand='';
const items=catalogItems.filter(x=>isListed(x));
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL=u=>{try{const v=new URL(u);return v.protocol==='https:'?v.href:'';}catch{return '';}};
const storage={get(k,f){try{return JSON.parse(localStorage.getItem(k))??f;}catch{return f;}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v));}catch{}}};
let favorites=storage.get('boutique-favorites-v2',[]);favorites=Array.isArray(favorites)?[...new Set(favorites.filter(Number.isInteger).map(id=>meta.aliases?.[id]||catalogItems.find(x=>x.id===id)?.review.aliasOf||id))].filter(id=>(meta.retained_ids||catalogItems.map(x=>x.id)).includes(id)):[];
storage.set('boutique-favorites-v2',favorites);
let compare=storage.get('boutique-compare-v2',[]);compare=Array.isArray(compare)?[...new Set(compare)].filter(id=>Number.isInteger(id)&&items.some(x=>x.id===id&&x.review.status!=='merged')).slice(0,3):[];
let preferences=normalizePreferences(storage.get('domyon-preferences',{}));
let recent=storage.get('domyon-recent',[]);recent=Array.isArray(recent)?[...new Set(recent.filter(Number.isInteger))].filter(id=>items.some(x=>x.id===id)).slice(0,8):[];
const initialState=()=>({...freshState(),valueFirst:true,preferredTypes:preferences.interests,personalized:storage.get('domyon-personalized',true)!==false});
let state=initialState(),results=[],detailId=null,detailOpener=null,toastTimer=null,searchTimer=null,displayedLimit=24,mobileFiltersOpen=false;
let compact=innerWidth<=600;
const icon=shopIcon;
const scrollCatalog=()=>{$('products').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});};
function filterDisclosure(){const fields=$('filterFields');fields.hidden=compact&&!mobileFiltersOpen;fields.inert=fields.hidden;$('mobileFiltersToggle').setAttribute('aria-expanded',String(compact&&mobileFiltersOpen));}
function renderChannels(){
 const order=['数码科技','家居生活','服饰穿搭','鞋履配件','个护美妆','玩具潮玩','运动户外','食品饮品','学习办公','生活精选','健康常备'];
 const types=order.filter(t=>items.some(x=>x.type===t));
 $('shopChannels').innerHTML=types.map((t,i)=>`<button data-type="${t}" class="channel ${i>=9?'channel-extra':''}"><span class="channel-icon">${icon(t)}</span><b>${t}</b><small>${items.filter(x=>x.type===t).length} 件</small></button>`).join('')+'<button data-open-categories class="channel"><span class="channel-icon all-channel">▦</span><b>全部分类</b><small>'+items.length+' 件</small></button>';
 $('entryChannels').innerHTML=types.slice(0,4).map(t=>`<button data-entry-type="${t}">${t}</button>`).join('');
 $('heroMarketIcons').innerHTML=['数码科技','服饰穿搭','玩具潮玩','家居生活'].map(t=>'<span>'+icon(t)+'</span>').join('');
}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2800);}
function openDialog(id){const d=$(id);if(!d.open)d.showModal();}
function closeDialog(id){$(id).close();}
function priceNote(p){return p.kind==='historical'?`历史参考价 · 原记录 ${p.observed_at}`:`参考价 · 核对于 ${p.observed_at}`;}
function statusHTML(x){return x.review.status==='documented'?'<span class="evidence">● 资料已核验<small>'+esc(x.source.region)+'</small></span>':'<span class="evidence pending">◌ 待核验<small>缺少型号或来源证据</small></span>';}
function categories(nav){$('categories').innerHTML=nav.types.map(({value:type,count})=>`<button data-type="${esc(type)}" aria-pressed="${state.type===type}" ${count?'':'disabled'}>${icon(type)}<span>${type||'全部分类'}</span><small>${count}</small></button>`).join('');$('channelCount').textContent=nav.types.filter(x=>x.value).length;}
function options(id,values,first,value){const selectedMissing=value&&!values.some(x=>x.value===value);$(id).innerHTML=`<option value="">${first}</option>`+values.map(v=>`<option value="${esc(v.value)}">${esc(v.value)} · ${v.count}</option>`).join('')+(selectedMissing?`<option value="${esc(value)}" disabled>${esc(value)} · 0</option>`:'');$(id).value=value;$(id).disabled=!values.length;}
function taxonomy(nav){options('groupSelect',nav.groups,'全部分组',state.group);options('categorySelect',nav.categories,'全部品类',state.category);}
function chips(){const active=[];if(state.max!==null)active.push(['max',state.max+' 元以内']);if(state.valueMode)active.push(['valueMode',state.valueMode==='hundred'?'100 元以内':'值得加预算 · 100–300 元']);if(state.personalOnly)active.push(['personalOnly','我的兴趣']);for(const [key,label] of [['brand',state.brand?brandDirectory(items,brandPicks).find(b=>b.key===state.brand)?.label||state.brand:''],['q',state.q?`搜索：${state.q}`:''],['type',state.type],['group',state.group],['category',state.category],['budget',BANDS.find(b=>b[0]===state.budget)?.[1]],['scene',state.scene],['priceKind',({'documented':'近期标价','historical':'历史参考','unknown':'尚未核价'})[state.priceKind]],['history',state.history&&(state.budget||parseSearch(state.q).max!==null||state.sort.startsWith('price-'))?'含历史参考价':'']])if(state[key]&&label)active.push([key,label]);if(state.scope!=='all')active.push(['scope',({documented:'有据精选',new:'本次新品',pending:'待核验',favorites:'我的收藏'})[state.scope]]);$('activeChips').innerHTML=active.map(([k,v])=>`<button data-remove="${k}" aria-label="移除${esc(v)}筛选">${esc(v)}<span>×</span></button>`).join('');$('reset').hidden=!active.length;}
function row(x){
 const historical=x.price.kind==='historical';
 const specs=Object.values(x.specs).slice(0,2).join(' · ');
 const why=upgradeReason(x),over=x.price.max>100;
 const note=over?`<div class="purchase-note ${why?'upgrade':''}"><b>${why?'为什么值得加预算':'加预算前，先确认'}</b>${esc(why||'型号和质量资料尚未核验，暂不建议为它加预算。')}</div>`:x.purchase?.value?`<div class="purchase-note"><b>百元实用之选</b>${esc(x.purchase.value)}</div>`:'';
 return `<article class="product-row product-card ${x.price.min!==x.price.max?'price-range':''}" data-product="${x.id}"><div class="card-utility"><button data-favorite="${x.id}" aria-label="${favorites.includes(x.id)?'取消收藏':'收藏'}${esc(x.product)}" aria-pressed="${favorites.includes(x.id)}">${favorites.includes(x.id)?'♥':'♡'}</button></div><div class="card-content"><div class="product-brand"><span class="brand-name">${esc(x.brand)}</span>${x.isNew?'<span class="new-badge">本次上新</span>':''}</div><button class="product-title" data-detail="${x.id}">${esc(x.product)}</button><div class="product-sub">${esc(x.type)} / ${esc(x.category)}</div>${specs?`<div class="product-specs">${esc(specs)}</div>`:''}<div class="card-price-line"><div class="product-price"><small class="reference-label">${historical?'历史参考价':'参考价'}</small><strong>${money(x.price)}</strong><small class="price-date">${historical?'原记录':'核对'} ${esc(x.price.observed_at)}</small></div></div>${note}<div class="product-operations"><button data-detail="${x.id}" class="card-detail">查看详情 <span aria-hidden="true">↗</span></button></div><div class="card-bottom"><span>${historical?'当前报价待核对':'价格来源可查'}</span><button data-compare="${x.id}" class="card-compare" aria-label="${compare.includes(x.id)?'移出对比':'加入对比'}${esc(x.product)}" aria-pressed="${compare.includes(x.id)}">${compare.includes(x.id)?'✓ 已对比':'⇄ 对比'}</button></div></div></article>`;
}
function render(){
  results=filterCatalog(items,state,favorites);const totalPages=Math.max(1,Math.ceil(results.length/24));state.page=Math.min(Math.max(1,state.page),totalPages);
  filterDisclosure();const filterCount=['group','category','budget','scene','priceKind'].filter(k=>state[k]).length;$('filterBadge').textContent=filterCount||'';$('filterBadge').hidden=!filterCount;
  $('search').value=state.q;$('clearSearch').hidden=!state.q;$('budgetSelect').value=state.budget;$('sortSelect').value=state.sort;$('sceneSelect').value=state.scene;$('priceKindSelect').value=state.priceKind;$('includeHistory').checked=state.history;
  const nav=catalogNavigation(items,state,favorites);categories(nav);taxonomy(nav);chips();$('personalizeToggle').checked=state.personalized;
  document.querySelectorAll('[data-scope]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.scope===state.scope)));
  document.querySelectorAll('[data-mobile]').forEach(b=>b.setAttribute('aria-current',(state.scope==='favorites'?b.dataset.mobile==='favorites':b.dataset.mobile==='discover')?'page':'false'));
  $('breadcrumb').textContent=[state.type||'全部分类',state.group,state.category].filter(Boolean).join(' / ');
  $('listTitle').firstChild.textContent=state.valueMode==='hundred'?'100 元以内':state.valueMode==='upgrade'?'值得加预算':state.personalOnly?'专属发现':state.scope==='favorites'?'我的收藏':state.scope==='new'?'本次上新':state.scope==='documented'?'有据精选':state.type||'全部好物';$('resultCount').textContent=results.length+' 件';
  const page=compact?results.slice(0,displayedLimit):results.slice((state.page-1)*24,state.page*24);$('products').innerHTML=page.length?page.map(row).join(''):`<div class="empty"><div class="eyebrow">重新匹配需求</div><h3>暂时没有符合条件的商品</h3><p>${state.scope==='favorites'&&!favorites.length?'点击商品旁的 ♡，即可加入收藏。':state.budget||parseSearch(state.q).max!==null?'可以调整预算，或在更多筛选中纳入历史参考价。':'试试减少关键词，或放宽分类与场景。'}</p><button data-reset>重置筛选</button></div>`;
  $('pageInfo').textContent=compact?`已显示 ${page.length} / ${results.length} 件`:results.length?`第 ${state.page} / ${totalPages} 页 · 显示 ${(state.page-1)*24+1}–${Math.min(state.page*24,results.length)} 件`:'0 件商品';$('prevPage').disabled=state.page===1;$('nextPage').disabled=state.page>=totalPages;$('pageButtons').hidden=compact;$('loadMore').hidden=!compact||page.length>=results.length;$('mobileBrowseCount').textContent=results.length+' 件好物';
  $('catalogNote').textContent=state.valueMode==='upgrade'?'100–300元的加预算候选，只按公开功能和明确用途给出理由；未进行实物质量测试。':state.valueMode==='hundred'?'按价格区间上限不超过100元筛选；历史参考价沿用原日期，不能视为现价。':state.scope==='documented'||state.scope==='new'?'参考价对应所列规格，价格日期与来源见详情。':(state.budget||parseSearch(state.q).max!==null)?(state.history?'预算区间按中值分档；“以内”按区间上限判断。历史价格已标明日期。':'预算仅使用近期有来源的人民币参考价。'):'历史参考价保留原记录日期，当前报价尚未核对。';
  $('favCount').textContent=favorites.filter(id=>items.some(x=>x.id===id)).length;$('totalStat').textContent=items.length;$('verifiedStat').textContent=items.filter(x=>x.price.kind==='documented').length;$('newStat').textContent=items.filter(x=>x.isNew).length;
  $('auditSummary').textContent=`当前展示 ${items.length} 件商品，其中 ${items.filter(x=>x.price.kind==='historical').length} 件为原目录历史参考价，${items.filter(x=>x.price.kind==='documented').length} 件有近期价格来源；${meta.hidden_count} 件未核价商品暂不展示。原目录记录与收藏均保留。`;
  document.querySelectorAll('.quick-browse [data-value]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.value===state.valueMode)));
  renderPersonalSummary();renderValuePicks();renderBrandTeasers();
  renderTray();document.dispatchEvent(new CustomEvent('catalog:render'));
}
function update(changes){clearTimeout(searchTimer);displayedLimit=24;Object.assign(state,changes,{page:1});render();}
function reset(){clearTimeout(searchTimer);displayedLimit=24;mobileFiltersOpen=false;state=initialState();render();}
function toggleFavorite(id){favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];storage.set('boutique-favorites-v2',favorites);render();if($('detailDialog').open)renderDetail();toast(favorites.includes(id)?'已加入收藏':'已取消收藏');}
function toggleCompare(id){if(compare.includes(id))compare=compare.filter(x=>x!==id);else{if(compare.length>=3){toast('最多对比 3 件商品，请先移除一件');return;}compare.push(id);}storage.set('boutique-compare-v2',compare);render();if($('detailDialog').open)renderDetail();}
function renderTray(){const xs=compare.map(id=>items.find(x=>x.id===id));$('compareTray').hidden=!xs.length;$('compareCount').textContent=`${xs.length} / 3`;$('compareNames').innerHTML=xs.map(x=>`<button data-compare="${x.id}" aria-label="从对比中移除${esc(x.product)}">${esc(x.model||x.product)} ×</button>`).join('');$('compareOpen').disabled=xs.length<2;}
function purchaseDetail(x){const why=upgradeReason(x);return `<div class="detail-purchase"><h4>${x.price.max>100?'为什么值得超过 100 元':'百元购买建议'}</h4><p>${esc(x.price.max>100?(why||'具体型号、规格或质量依据不足，暂不作超预算推荐。'):(x.purchase?.value||'历史记录只供预算浏览，购买前先核对实际型号、包装和当前售价。'))}</p><small>购买建议依据公开功能与适用条件；未进行实物质量测试。</small></div>`;}
function renderDetail(){
 const x=items.find(x=>x.id===detailId);if(!x)return;
 const historical=x.price.kind==='historical',hasSpecs=Object.keys(x.specs).length>0;
 const idx=results.findIndex(x=>x.id===detailId);$('prevDetail').disabled=idx<=0;$('nextDetail').disabled=idx<0||idx>=results.length-1;
 const list=xs=>'<ul>'+xs.map(v=>'<li>'+esc(v)+'</li>').join('')+'</ul>';
 const sourceLink=(url,label)=>{const safe=safeURL(url);return safe?`<a class="source-link" target="_blank" href="${esc(safe)}" rel="noopener noreferrer"><span>${esc(label)}<small>${esc(new URL(safe).hostname)}</small></span><span aria-hidden="true">↗</span></a>`:'';};
 const caption=historical?'历史参考价':'参考价格';
 const priceExplanation=historical?'原目录的价格区间，尚未核对当前售价、具体型号及包装。':'对应所列型号与规格，实际售价及库存以销售方为准。';
 const overview=x.overview||(historical?`${x.product}，原目录归于${x.type} / ${x.category}。具体型号与规格资料尚未补全。`:x.variant);
 const priceEvidence=historical?'<p>原记录未保存价格来源网址，当前报价待核对。此区间不能视为指定型号或包装的现价。</p>':sourceLink(x.price.url,x.price.label||'参考价格来源');
 const sources=x.source.urls.map(source=>sourceLink(source.url,source.label)).join('');
 $('detailContent').innerHTML=`<div class="detail-hero"><div class="detail-heading"><div class="product-brand">${esc(x.brand)} · ${esc(x.category)}</div><h2 id="detailTitle">${esc(x.product)}</h2><p class="detail-variant">${esc(historical?'原目录商品 · 具体型号与包装待核对':x.variant)}</p><div class="detail-highlights">${(x.highlights||[]).map(v=>'<span>'+esc(v)+'</span>').join('')}</div></div><aside class="detail-price-panel ${x.price.min!==x.price.max?'price-range':''}"><span>${caption}</span><div class="detail-price">${money(x.price)}</div><small>${historical?'原记录日期':'核对日期'} ${esc(x.price.observed_at)}</small><p>${priceExplanation}</p><button data-favorite="${x.id}" class="primary" aria-pressed="${favorites.includes(x.id)}">${favorites.includes(x.id)?'♥ 已收藏':'♡ 收藏这件好物'}</button></aside></div><nav class="detail-tabs" aria-label="详情章节"><button data-detail-section="detailOverview">商品概览</button><button data-detail-section="detailSpecs">规格信息</button><button data-detail-section="detailUsage">使用与包装</button><button data-detail-section="detailPriceSource">价格依据</button></nav><div class="detail-body"><section id="detailOverview"><h3>商品概览</h3><p>${esc(overview)}</p>${purchaseDetail(x)}<dl class="identity-list"><div><dt>具体型号</dt><dd>${esc(x.model||'原记录未注明')}</dd></div><div><dt>商品品类</dt><dd>${esc(x.type+' / '+x.group+' / '+x.category)}</dd></div>${x.fit.length?`<div><dt>适用场景</dt><dd>${esc(x.fit.join('、'))}</dd></div>`:''}</dl></section><section id="detailSpecs"><h3>${hasSpecs?'完整规格':'规格信息'}</h3>${hasSpecs?`<dl class="spec-list">${Object.entries(x.specs).map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`:'<p>原记录未保存可对应到具体型号的参数、材质与尺寸资料。</p>'}</section><section id="detailUsage"><h3>使用与包装</h3><div class="usage-grid"><div><h4>包装内容</h4>${list(x.package||['原记录未注明包装内容，需核对实际销售版本。'])}</div><div><h4>日常使用</h4>${list(x.care||(historical?['按实际型号的说明书确认使用与保养方式。']:x.limits))}</div></div><div class="detail-limit"><h4>购买前确认</h4>${list(historical?['确认实际型号、包装数量、规格与当前价格。']:x.limits)}</div></section><section id="detailPriceSource"><h3>价格依据</h3><dl class="identity-list"><div><dt>价格口径</dt><dd>${caption} · 人民币</dd></div><div><dt>价格区间</dt><dd>${money(x.price)}</dd></div><div><dt>${historical?'原记录日期':'价格日期'}</dt><dd>${esc(x.price.observed_at)}</dd></div>${!historical?`<div><dt>对应规格</dt><dd>${esc(x.price.variant||x.variant)}</dd></div>`:''}</dl><p>${esc(x.price.note||priceExplanation)}</p>${priceEvidence}<details class="detail-sources"><summary>产品资料与说明书</summary>${sources||'<p>原记录未保存产品资料来源或说明书。</p>'}${x.source.checked_at?'<p>产品资料核对于 '+esc(x.source.checked_at)+'。实物测试：未进行；购买时请确认批次、当地售后与销售包装。</p>':'<p>型号、规格与当前价格尚未核验。</p>'}</details></section><div class="detail-actions"><button data-compare="${x.id}" class="primary" aria-pressed="${compare.includes(x.id)}">${compare.includes(x.id)?'移出对比':'⇄ 加入对比'}</button><button data-close="detailDialog">继续逛逛 →</button></div></div>`;
}
function showDetail(id,opener){if(!items.some(x=>x.id===id))return;if($('personalDialog').open)$('personalDialog').close();if($('brandDialog').open)$('brandDialog').close();hideSuggestions();recent=[id,...recent.filter(v=>v!==id)].slice(0,8);storage.set('domyon-recent',recent);renderPersonalSummary();detailId=id;detailOpener=opener;renderDetail();openDialog('detailDialog');$('detailDialog').scrollTop=0;}
function renderCompare(){const xs=compare.map(id=>items.find(x=>x.id===id));if(xs.length<2)return;const fields=[['型号 / 版本',x=>esc(x.model||'待核验')+'<p>'+esc(x.variant)+'</p>'],['价格 / 日期',x=>money(x.price)+'<p>'+esc(priceNote(x.price))+'</p>'],['资料状态',x=>statusHTML(x)],['关键规格',x=>Object.entries(x.specs).map(([k,v])=>'<p>'+esc(k)+'：'+esc(v)+'</p>').join('')||'待核验'],['适用场景',x=>esc(x.fit.join(' / ')||'待核验')],['需要确认',x=>x.limits.map(v=>'<p>'+esc(v)+'</p>').join('')],['原厂来源',x=>x.source.urls.map(s=>'<p><a rel="noopener noreferrer" href="'+esc(safeURL(s.url))+'">'+esc(s.label)+' ↗</a></p>').join('')||'暂无']];
 $('compareContent').innerHTML=`<p class="muted">${comparable(xs)?'同品类对比；仍需核对包装、地区和配件差异。':'所选商品跨品类，规格与价格不能直接用于判断哪件更划算。'} 价格保留各自口径与日期，不把历史区间当作当前成交价。</p><div class="table-wrap"><table class="compare-table"><thead><tr><th scope="col">对比项目</th>${xs.map(x=>'<th scope="col">'+esc(x.product)+'</th>').join('')}</tr></thead><tbody>${fields.map(([label,fn])=>'<tr><th scope="row">'+label+'</th>'+xs.map(x=>'<td>'+fn(x)+'</td>').join('')+'</tr>').join('')}</tbody></table></div>`;openDialog('compareDialog');
}
function theme(){const isLight=document.documentElement.dataset.theme==='light';$('themeLabel').textContent=isLight?'黑夜':'白昼';$('themeToggle').setAttribute('aria-label',isLight?'切换黑夜主题':'切换白昼主题');$('themeToggle').firstElementChild.textContent=isLight?'☾':'☼';$('entryThemeToggle').textContent=isLight?'☾':'☼';$('entryThemeToggle').setAttribute('aria-label',isLight?'切换黑夜主题':'切换白昼主题');document.querySelector('meta[name=theme-color]').content=isLight?'#f9f6f0':'#090f1b';}
document.querySelector('.header .brand').addEventListener('click',e=>{e.preventDefault();reset();window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});$('heroTitle').focus({preventScroll:true});});
$('budgetSelect').insertAdjacentHTML('beforeend',BANDS.map(b=>`<option value="${b[0]}">${b[1]}</option>`).join(''));
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;if(d.brandOpen!==undefined)openBrands(d.brandOpen);else if(d.brandChoice)renderBrandProfile(d.brandChoice);else if(d.brandBrowse){$('brandDialog').close();state=initialState();update({brand:d.brandBrowse});scrollCatalog();}else if(d.personalOpen!==undefined)openPersonal();else if(d.suggest){const x=items.find(v=>v.id===Number(d.suggest));if(x){update({q:x.product,brand:'',type:'',group:'',category:'',scope:'all',budget:'',max:null,valueMode:'',personalOnly:false});hideSuggestions();scrollCatalog();}}else if(d.value!==undefined){state=initialState();update({valueMode:d.value});scrollCatalog();}else if(d.close)closeDialog(d.close);else if(d.detailSection){$(d.detailSection)?.scrollIntoView({behavior:'smooth',block:'start'});}else if(d.type!==undefined){if(b.closest('.shop-scenes'))state=initialState();mobileFiltersOpen=false;update({type:d.type,group:'',category:''});scrollCatalog();}else if(d.openCategories!==undefined){reset();document.dispatchEvent(new CustomEvent('city:categories'));}else if(d.scope)update({scope:d.scope,type:'',group:'',category:''});else if(d.shortcut){state=initialState();mobileFiltersOpen=false;update({scope:d.shortcut});scrollCatalog();}else if(d.detail)showDetail(Number(d.detail),b);else if(d.favorite)toggleFavorite(Number(d.favorite));else if(d.compare)toggleCompare(Number(d.compare));else if(d.reset!==undefined)reset();else if(d.remove){const k=d.remove;update({...{[k]:k==='scope'?'all':k==='history'||k==='personalOnly'?false:k==='max'?null:''},...(k==='type'?{group:'',category:''}:k==='group'?{category:''}:{})});}});
$('searchForm').addEventListener('submit',e=>{e.preventDefault();clearTimeout(searchTimer);update({q:$('search').value.trim()});hideSuggestions();$('products').scrollIntoView({behavior:'smooth',block:'start'});});
$('search').addEventListener('input',()=>{clearTimeout(searchTimer);const q=$('search').value;showSuggestions(q);searchTimer=setTimeout(()=>update({q}),100);});
$('products').addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;const card=e.target.closest('.product-card');if(!card)return;const r=card.getBoundingClientRect();if(r.width&&r.height){card.style.setProperty('--hover-x',((e.clientX-r.left)/r.width*100)+'%');card.style.setProperty('--hover-y',((e.clientY-r.top)/r.height*100)+'%');}});
$('clearSearch').addEventListener('click',()=>{clearTimeout(searchTimer);update({q:''});hideSuggestions();$('search').focus();});$('reset').addEventListener('click',reset);
$('mobileFiltersToggle').addEventListener('click',()=>{mobileFiltersOpen=!mobileFiltersOpen;filterDisclosure();});
$('applyMobileFilters').addEventListener('click',()=>{mobileFiltersOpen=false;filterDisclosure();scrollCatalog();$('products').focus({preventScroll:true});});
$('loadMore').addEventListener('click',()=>{displayedLimit+=24;render();});
window.addEventListener('resize',()=>{const next=innerWidth<=600;if(next!==compact){compact=next;mobileFiltersOpen=false;render();}});
$('groupSelect').addEventListener('change',e=>update({group:e.target.value,category:''}));$('categorySelect').addEventListener('change',e=>update({category:e.target.value}));
for(const [id,k] of [['budgetSelect','budget'],['sortSelect','sort'],['sceneSelect','scene'],['priceKindSelect','priceKind']])$(id).addEventListener('change',e=>update({[k]:e.target.value}));$('includeHistory').addEventListener('change',e=>update({history:e.target.checked}));
$('personalizeToggle').addEventListener('change',e=>{storage.set('domyon-personalized',e.target.checked);update({personalized:e.target.checked});});
$('recommendationInfo').addEventListener('click',()=>openDialog('standardsDialog'));
document.addEventListener('city:enter',e=>{state=initialState();mobileFiltersOpen=false;update({scope:e.detail?.scope||'all',q:e.detail?.q||'',type:e.detail?.type||''});});
document.addEventListener('city:discover',()=>{state=initialState();mobileFiltersOpen=false;update({scope:'all'});$('products').scrollIntoView({behavior:'smooth',block:'start'});$('products').focus({preventScroll:true});});
document.addEventListener('city:favorites',()=>$('favoritesShortcut').click());
$('moreFilters').addEventListener('click',()=>openDialog('filterDialog'));$('standardsButton').addEventListener('click',()=>openDialog('standardsDialog'));$('favoritesShortcut').addEventListener('click',()=>{state=initialState();update({scope:'favorites'});});
for(const [id,delta] of [['prevPage',-1],['nextPage',1]])$(id).addEventListener('click',()=>{state.page+=delta;render();$('products').scrollIntoView({behavior:'smooth',block:'start'});});
for(const [id,delta] of [['prevDetail',-1],['nextDetail',1]])$(id).addEventListener('click',()=>{const idx=results.findIndex(x=>x.id===detailId);if(results[idx+delta]){detailId=results[idx+delta].id;renderDetail();$('detailDialog').scrollTop=0;}});
$('detailDialog').addEventListener('close',()=>{if(detailOpener?.isConnected)detailOpener.focus();else (document.querySelector('#products [data-detail=\"'+detailId+'\"]')||$('search')).focus();});
function toggleTheme(){const v=document.documentElement.dataset.theme==='light'?'dark':'light';document.documentElement.dataset.theme=v;try{localStorage.setItem('boutique-theme',v);}catch{}theme();document.dispatchEvent(new CustomEvent('city:theme'));}
$('themeToggle').addEventListener('click',toggleTheme);$('entryThemeToggle').addEventListener('click',toggleTheme);
$('compareOpen').addEventListener('click',renderCompare);$('clearCompare').addEventListener('click',()=>{compare=[];storage.set('boutique-compare-v2',compare);render();});
$('exportButton').addEventListener('click',()=>{const csv=[['商品','品牌','型号','分类','价格口径','参考最低价','参考最高价','价格日期','审核状态','来源','价格依据'].join(','),...results.map(x=>[x.product,x.brand,x.model,x.type,x.price.kind,x.price.min,x.price.max,x.price.observed_at,x.review.status,x.source.urls.map(s=>s.url).join(' '),x.price.url].map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(','))].join('\r\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='精品之城-当前商品.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('已导出当前筛选结果');});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)){e.preventDefault();$(document.body.classList.contains('shop-active')?'search':'entrySearch').focus();}if(e.key==='Escape'){const ds=[...document.querySelectorAll('dialog[open]')];if(ds.length){e.preventDefault();const top=$('portalDialog').open?$('portalDialog'):ds.at(-1);top.close();}}});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
function hideSuggestions(){$('searchSuggestions').hidden=true;$('search').setAttribute('aria-expanded','false');}
function showSuggestions(q){const xs=suggestions(items,q);$('searchSuggestions').innerHTML=xs.map(x=>`<button type="button" data-suggest="${x.id}"><strong>${esc(x.product)}</strong><small>${money(x.price)}</small></button>`).join('');$('searchSuggestions').hidden=!xs.length;$('search').setAttribute('aria-expanded',String(!!xs.length));}
$('search').addEventListener('keydown',e=>{if(e.key==='ArrowDown'&&!$('searchSuggestions').hidden){e.preventDefault();$('searchSuggestions').querySelector('button')?.focus();}if(e.key==='Escape'){hideSuggestions();}});
$('searchSuggestions').addEventListener('keydown',e=>{const buttons=[...$('searchSuggestions').querySelectorAll('button')],i=buttons.indexOf(document.activeElement);if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();buttons[(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus();}if(e.key==='Escape'){hideSuggestions();$('search').focus();}});
document.addEventListener('pointerdown',e=>{if(!$('searchForm').contains(e.target))hideSuggestions();});
$('searchForm').addEventListener('focusout',e=>{if(!$('searchForm').contains(e.relatedTarget))hideSuggestions();});
function applyPreferences(){document.documentElement.dataset.accent=preferences.accent;document.documentElement.dataset.intensity=preferences.intensity;document.documentElement.dataset.cosmicTone=preferences.cosmicTone;document.dispatchEvent(new CustomEvent('city:preferences',{detail:preferences}));}
function renderPersonalSummary(){
 $('personalGreeting').textContent=(preferences.nickname||'好物探索家')+'，欢迎回来。';
 const interests=preferences.interests.length?preferences.interests.join(' / '):'随心发现';
 $('personalSummary').textContent=preferences.budget+' 元预算 · '+interests+(preferences.scene?' · '+preferences.scene:'');$('recentCount').textContent=recent.length;
}
function renderValuePicks(){
 const xs=filterCatalog(items,{...initialState(),scope:'documented',max:100},favorites).slice(0,3);
 $('valuePicks').innerHTML=xs.map(x=>`<button class="value-pick" data-detail="${x.id}"><span class="pick-label">¥100 以内 · 公开资料可查</span><strong>${esc(x.product)}</strong><p>${esc(x.purchase?.value||Object.values(x.specs).slice(0,2).join(' · '))}</p><span class="pick-price">${money(x.price)} <span aria-hidden="true">↗</span></span><small>参考价 ${esc(x.price.observed_at)} · 库存另核对</small></button>`).join('');
}
function fillPersonal(){
 $('personalNickname').value=preferences.nickname;$('personalBudget').value=preferences.budget;$('personalScene').value=preferences.scene;$('personalIntensity').value=preferences.intensity;$('personalCosmicTone').value=preferences.cosmicTone;
 $('personalInterests').innerHTML=PERSONAL_TYPES.map(t=>`<label><input type="checkbox" name="interest" value="${t}" ${preferences.interests.includes(t)?'checked':''}>${t}</label>`).join('');
 $('personalForm').querySelectorAll('[name=accent]').forEach(x=>x.checked=x.value===preferences.accent);
 $('personalEffects').checked=storage.get('domyon-effects',true)!==false;$('personalSaved').value='';renderRecent();
}
function renderRecent(){const xs=recent.map(id=>items.find(x=>x.id===id)).filter(Boolean);$('recentProducts').innerHTML=xs.length?xs.map(x=>`<button type="button" data-detail="${x.id}"><span>${esc(x.product)}</span><span>↗</span></button>`).join(''):'<p>还没有浏览记录，先去发现一件喜欢的好物。</p>';$('clearRecent').disabled=!xs.length;}
function openPersonal(){hideSuggestions();fillPersonal();openDialog('personalDialog');}
$('recentShortcut').addEventListener('click',()=>{openPersonal();$('recentProducts').scrollIntoView({block:'nearest'});});
$('personalForm').addEventListener('submit',e=>{e.preventDefault();preferences=normalizePreferences({nickname:$('personalNickname').value,budget:Number($('personalBudget').value),scene:$('personalScene').value,interests:[...$('personalForm').querySelectorAll('[name=interest]:checked')].map(x=>x.value),accent:$('personalForm').querySelector('[name=accent]:checked')?.value,intensity:$('personalIntensity').value,cosmicTone:$('personalCosmicTone').value});storage.set('domyon-preferences',preferences);storage.set('domyon-effects',$('personalEffects').checked);document.dispatchEvent(new CustomEvent('city:effects',{detail:$('personalEffects').checked}));applyPreferences();update({preferredTypes:preferences.interests});$('personalSaved').value='已保存，新的偏好已生效。';toast('我的星球已更新');});
$('resetPersonal').addEventListener('click',()=>{preferences=normalizePreferences();storage.set('domyon-preferences',preferences);applyPreferences();update({preferredTypes:[]});fillPersonal();$('personalSaved').value='已恢复默认偏好。';});
$('clearRecent').addEventListener('click',()=>{recent=[];storage.set('domyon-recent',recent);renderRecent();renderPersonalSummary();});
$('personalDiscover').addEventListener('click',()=>{state=initialState();const types=preferences.interests.length?preferences.interests:[...new Set(items.filter(x=>favorites.includes(x.id)).map(x=>x.type))];update({scope:'documented',max:preferences.budget,scene:preferences.scene,preferredTypes:types,personalOnly:true});scrollCatalog();});
renderChannels();applyPreferences();theme();render();

function renderBrandTeasers(){
 const groups=brandDirectory(items,brandPicks).filter(b=>b.picks.length).slice(0,4);
 $('brandPicks').innerHTML=groups.map(b=>{const p=b.picks[0],x=items.find(x=>x.id===p.product_id);return `<button class="brand-pick" data-brand-open="${esc(b.key)}"><span class="brand-pick-top">${esc(b.label)}<span aria-hidden="true">↗</span></span><small>${esc(p.category)} · ${x.price.max<=100?'百元优先':'有条件升级'}</small><strong>${esc(x.product)}</strong><p>${esc(p.reason)}</p><span class="brand-pick-price">${money(x.price)}<small>参考价 ${esc(x.price.observed_at)}</small></span></button>`;}).join('');
}
function openBrands(key=''){
 hideSuggestions();$('brandSearch').value='';selectedBrand=key||brandDirectory(items,brandPicks)[0]?.key||'';renderBrandDirectory();renderBrandProfile(selectedBrand);openDialog('brandDialog');
}
function renderBrandDirectory(){
 const groups=brandDirectory(items,brandPicks,$('brandSearch').value);
 $('brandDirectory').innerHTML=groups.length?groups.map(b=>`<button data-brand-choice="${esc(b.key)}" aria-pressed="${b.key===selectedBrand}"><b>${esc(b.label)}</b><small>${b.picks.length?'有用途首选':b.documented?'同类比较待补充':'资料待核验'} · ${b.count} 件</small></button>`).join(''):'<p class="muted">没有匹配的品牌，试试中文名或英文名。</p>';
}
function renderBrandProfile(key){
 selectedBrand=key;const group=brandDirectory(items,brandPicks).find(b=>b.key===key);
 renderBrandDirectory();if(!group){$('brandProfile').innerHTML='';return;}
 const picks=group.picks.map(p=>{const x=items.find(v=>v.id===p.product_id),alternatives=p.alternatives.map(a=>({record:items.find(v=>v.id===a.product_id),...a}));return `<article class="brand-profile-card"><span class="eyebrow">${esc(p.category)} / 用途首选</span><h3>${esc(x.product)}</h3><p class="brand-scope">${esc(p.scope)}</p><div class="brand-selected-price">${money(x.price)} <small>参考价 · ${esc(x.price.observed_at)}</small></div><h4>为什么先选它</h4><p>${esc(p.reason)}</p><div class="brand-criteria">${p.criteria.map(c=>'<span>'+esc(c)+'</span>').join('')}</div><div class="brand-alternatives"><h4>换一种需求，怎么选</h4>${alternatives.map(a=>`<div><button data-detail="${a.record.id}">${esc(a.record.product)} ↗</button><strong>${money(a.record.price)}</strong><p>${esc(a.tradeoff)}</p><small>参考价 ${esc(a.record.price.observed_at)}</small></div>`).join('')}</div><details class="brand-evidence"><summary>比较范围与原厂依据</summary><ul>${p.limitations.map(l=>'<li>'+esc(l)+'</li>').join('')}</ul>${[x,...alternatives.map(a=>a.record)].map(v=>`<p>${esc(v.product)} · ${esc(v.source.checked_at)}${v.source.urls.map(src=>{const u=safeURL(src.url);return u?` <a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(src.label||'官方产品资料')} ↗</a>`:'';}).join('')}</p>`).join('')}</details><button data-detail="${x.id}" class="primary">查看首选详情 ↗</button></article>`;}).join('');
 $('brandProfile').innerHTML=`<div class="brand-profile-head"><h3>${esc(group.label)}</h3><button data-brand-browse="${esc(group.key)}">逛这个品牌的 ${group.count} 件商品 ↗</button></div>${picks||`<div class="brand-empty"><span aria-hidden="true">✧</span><h4>先补全依据，再给你首选。</h4><p>${group.documented?'已有可查资料，但还缺少适合做同类比较的完整候选。':'当前收录主要是历史参考记录，型号、规格和现价仍待核对。'} 暂时无法判断哪件最适合你。</p></div>`}`;
}
$('brandSearch').addEventListener('input',renderBrandDirectory);
